import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Проблемы администратора","description":"","frontmatter":{"pageId":"admins/troubleshooting","contentRevision":5},"headers":[],"relativePath":"ru/admins/troubleshooting.md","filePath":"ru/admins/troubleshooting.md"}'),o={name:"ru/admins/troubleshooting.md"};function l(n,a,s,d,h,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="проблемы-администратора" tabindex="-1">Проблемы администратора <a class="header-anchor" href="#проблемы-администратора" aria-label="Permalink to &quot;Проблемы администратора&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p><strong>Сервер не стартует:</strong> проверь SDK/runtime, права DataDir, занятый порт, сертификат и сообщение валидации Options. Не устраняй ошибку удалением БД.</p><p><strong>Панель работает, игра нет:</strong> проверь HTTP/2/gRPC, прокси, TLS и игровые версии. Простая загрузка HTML проверяет не весь транспорт.</p><p><strong>401/403:</strong> сверяй legacy/именованный токен, scopes, cookie CSRF и срок сессии; не повышай интеграцию до admin без причины.</p><p><strong>Зависший расчёт:</strong> проверь заморозку, долг, угрозу, срок и id эскроу; изучи аудит и состояние до повторения мутации.</p><p><strong>Не проходит restore:</strong> остановлен ли сервер, цела ли копия, совпадают ли БД/сейвы; сохрани текущие данные до дальнейших действий.</p><h2 id="incident-triage" tabindex="-1">Порядок расследования серверного отказа <a class="header-anchor" href="#incident-triage" aria-label="Permalink to &quot;Порядок расследования серверного отказа {#incident-triage}&quot;">​</a></h2><ol><li>Запиши версию, точное время и id, затем воспроизведи безопасным чтением.</li><li>Определи слой: процесс/порт → TLS/HTTP2 → auth/scope → feature-state → сохранение/диск. Не смешивай 403 с недоступным портом.</li><li>Прочти Options error или redacted log. При save-ошибке сохрани DB/файлы и клиентский журнал; не удаляй base/delta.</li><li>Проверь гипотезу на изолированной копии. Изменяй только один причинный фактор.</li><li>После исправления повтори исходный сценарий: login/save/replay, а не только health.</li></ol><p>При недостатке доказательств останови опасные действия. Отсутствие строки в ограниченном списке API или public feed не доказывает, что операция не происходила.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не выводи секреты окружения в общий тикет. Не завершай чужие процессы. Если причина неизвестна, собери точный отказ, версию, время и обезличенный фрагмент лога; не объявляй проблему решённой по одному /health.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./monitoring">Мониторинг и журнал событий</a></li><li><a href="./backup-recovery">Резервные копии и восстановление</a></li><li><a href="./../players/troubleshooting">Проблемы игрока</a></li></ul>',15)])])}const g=e(o,[["render",l]]);export{u as __pageData,g as default};
